const MANUALS = [
  { id:"bp70m65", label:"BP-70M65 Series", subtitle:"B&W Digital MFP", models:"BP-50M26/31/36/45/55/65 · BP-70M31/36/45/55/65", color:"#00ff88" },
  { id:"bp70c45", label:"BP-70C45 Series", subtitle:"Full Color Digital MFP", models:"BP-50C26/31/36/45/55/65 · BP-60C31/36/45 · BP-70C31/36/45/55/65", color:"#00ccff" },
  { id:"mx6071",  label:"MX-5071 / MX-6071 Series", subtitle:"Full Color Digital MFP", models:"MX-5071S/6071S · MX-5051/6051 · MX-5071/6071", color:"#ff9900" },
  { id:"mxm6071", label:"MX-M6071 Series", subtitle:"B&W Digital MFP", models:"MX-M2651/3051/3551/4051/5051/6051 · MX-M3071/3571/4071/5071/6071", color:"#cc88ff" },
  { id:"mx4071",  label:"MX-4071 Series", subtitle:"Full Color Digital MFP", models:"MX-2651/3051/3551/4051 · MX-3061/3561/4061 · MX-3071/3571/4071", color:"#ff4488" },
];

const SYSTEM_PROMPT = `You are AONE-AI, an expert technical assistant for Sharp MFP service technicians at AONE. You have been given the complete Section 7 (Self Diagnostics and Trouble Codes) extracted directly from the official Sharp service manual for the selected model.

STRICT RULES:
1. ONLY answer using the manual content provided. No outside knowledge, no guessing.
2. If a code or procedure is NOT in the provided content, say clearly: "That code/information was not found in the Self Diagnostics section of this manual."
3. For every error/trouble code, always provide: Code, Detection source, Cause(s), and Check & Remedy steps — exactly as listed in the manual.
4. Use numbered steps for procedures. Use bullet points for causes/checks.
5. Be direct and technical — these are trained field service technicians in the field.
6. Never fabricate codes, causes, or remedies.
7. If a tech asks about a topic outside self-diagnostics (e.g. disassembly), note that this tool covers Section 7 only.`;

export default function AoneAI() {
  const [phase, setPhase] = useState("gate");
  const [accessInput, setAccessInput] = useState("");
  const [accessError, setAccessError] = useState(false);
  const [selectedManual, setSelectedManual] = useState(null);
  const [messages, setMessages] = useState([]);
  const [input, setInput] = useState("");
  const [aiLoading, setAiLoading] = useState(false);
  const [glitch, setGlitch] = useState(false);
  const chatEndRef = useRef(null);
  const inputRef = useRef(null);

  useEffect(() => { chatEndRef.current?.scrollIntoView({ behavior:"smooth" }); }, [messages, aiLoading]);

  useEffect(() => {
    const id = setInterval(() => { setGlitch(true); setTimeout(() => setGlitch(false), 120); }, 9000);
    return () => clearInterval(id);
  }, []);

  const handleAccess = () => {
    if (accessInput.trim().toUpperCase() === ACCESS_CODE) { setPhase("select"); setAccessError(false); }
    else { setAccessError(true); setAccessInput(""); }
  };

  const selectManual = (m) => {
    setSelectedManual(m);
    setMessages([{
      role:"assistant",
      content:`**${m.label} — Self Diagnostics & Trouble Codes**\nModels: ${m.models}\n\nSection 7 loaded. Ask me about any error code, trouble code, cause, or remedy — I answer directly from the manual.`
    }]);
    setPhase("chat");
  };

  const sendMessage = async () => {
    if (!input.trim() || aiLoading || !selectedManual) return;
    const userMsg = { role:"user", content:input.trim() };
    const newMsgs = [...messages, userMsg];
    setMessages(newMsgs);
    setInput("");
    setAiLoading(true);

    const manualText = MANUAL_CONTENT[selectedManual.id] || "";
    const apiMsgs = newMsgs.map(m => ({ role:m.role, content:m.content }));
    apiMsgs[0] = {
      role:"user",
      content:`MANUAL: ${selectedManual.label}\nSECTION: 7 — Self Diagnostics and Trouble Codes\n\nMANUAL CONTENT:\n${manualText}\n\n---\n\nTECH QUERY: ${apiMsgs[0].content}`
    };

    try {
      const res = await fetch("/api/chat", {
        method:"POST",
        headers:{"Content-Type":"application/json"},
        body:JSON.stringify({ model:"claude-sonnet-4-6", max_tokens:1024, system:SYSTEM_PROMPT, messages:apiMsgs })
      });
      const data = await res.json();
      console.log("API status:", res.status, "data type:", data.type);
      let reply = "No response received.";
      if (data.content && Array.isArray(data.content) && data.content.length > 0) {
        reply = data.content.map(b => b.text||"").join("") || "No response received.";
      } else if (data.error) {
        reply = "⚠ API Error: " + (data.error.message || JSON.stringify(data.error));
      } else if (data.type === "error") {
        reply = "⚠ Error: " + (data.error?.message || JSON.stringify(data));
      }
      setMessages([...newMsgs, { role:"assistant", content:reply }]);
    } catch(e) {
      console.error("Fetch error:", e);
      setMessages([...newMsgs, { role:"assistant", content:"⚠ Connection error: " + e.message }]);
    }
    setAiLoading(false);
    setTimeout(() => inputRef.current?.focus(), 100);
  };

  const fmt = t => t
    .replace(/\*\*(.*?)\*\*/g, '<span style="color:#00ff88;font-weight:bold">$1</span>')
    .replace(/^(\d+\.\s)/gm, '<span style="color:#00ff88">$1</span>')
    .replace(/\n/g, "<br/>");

  const accent = selectedManual?.color || "#00ff88";

  return (
    <div style={{ fontFamily:"'Share Tech Mono',monospace", minHeight:"100vh", background:"#000", position:"relative", overflow:"hidden" }}>
      <style>{`
        @import url('https://fonts.googleapis.com/css2?family=Share+Tech+Mono&family=Orbitron:wght@400;700;900&display=swap');
        *{box-sizing:border-box;margin:0;padding:0;}
        .scanlines{position:fixed;inset:0;pointer-events:none;z-index:9999;background:repeating-linear-gradient(0deg,transparent,transparent 3px,rgba(0,255,136,.007) 3px,rgba(0,255,136,.007) 4px);}
        .gridbg{position:fixed;inset:0;pointer-events:none;background-image:linear-gradient(rgba(0,255,136,.022) 1px,transparent 1px),linear-gradient(90deg,rgba(0,255,136,.022) 1px,transparent 1px);background-size:48px 48px;}
        .blink{animation:blink 1s step-end infinite;}@keyframes blink{50%{opacity:0;}}
        .glitch{animation:gfx .12s linear;}@keyframes gfx{25%{transform:translate(-2px,1px);filter:hue-rotate(90deg);}75%{transform:translate(2px,-1px);}100%{filter:none;}}
        ::-webkit-scrollbar{width:4px;}::-webkit-scrollbar-track{background:transparent;}::-webkit-scrollbar-thumb{background:rgba(0,255,136,.18);}
        @keyframes spin{to{transform:rotate(360deg);}}
        @keyframes tda{0%,80%,100%{opacity:.2;transform:scale(.7);}40%{opacity:1;transform:scale(1);}}
        textarea{color:#ddd;}
        textarea::placeholder{color:#1a3322 !important;}
        input::placeholder{color:#1a4433;}
        button{transition:all .2s;}
      `}</style>
      <div className="gridbg"/>
      <div className="scanlines"/>

      {/* ── GATE ── */}
      {phase==="gate" && (
        <div style={{minHeight:"100vh",display:"flex",alignItems:"center",justifyContent:"center",position:"relative",zIndex:10}}>
          <div style={{border:"1px solid rgba(0,255,136,.2)",background:"rgba(0,4,2,.97)",padding:"52px 60px",minWidth:460,textAlign:"center",position:"relative",boxShadow:"0 0 100px rgba(0,255,136,.05),inset 0 0 60px rgba(0,255,136,.01)"}}>
            <div style={{position:"absolute",top:-1,left:40,right:40,height:1,background:"linear-gradient(90deg,transparent,rgba(0,255,136,.55),transparent)"}}/>
            <div style={{position:"absolute",bottom:-1,left:60,right:60,height:1,background:"linear-gradient(90deg,transparent,rgba(0,255,136,.2),transparent)"}}/>
            {[["8px","8px","1px 0 0 1px"],["8px","right:8px","1px 1px 0 0"],["bottom:8px","8px","0 0 1px 1px"],["bottom:8px","right:8px","0 1px 1px 0"]].map(([t,l,bw],i)=>(
              <div key={i} style={{position:"absolute",width:12,height:12,borderColor:"rgba(0,255,136,.4)",borderStyle:"solid",borderWidth:bw,[t.includes("bottom")?"bottom":"top"]:8,[l.includes("right")?"right":"left"]:8}}/>
            ))}
            <div style={{fontFamily:"'Orbitron',monospace",fontSize:11,color:"#00ff88",letterSpacing:8,marginBottom:4}}>AONE</div>
            <div style={{fontFamily:"'Orbitron',monospace",fontSize:36,fontWeight:900,color:"#fff",letterSpacing:4,marginBottom:2}}>
              A<span style={{color:"#00ff88"}}>·</span>ONE<span style={{color:"#00ff88",fontSize:28}}> AI</span>
            </div>
            <div style={{fontSize:10,color:"#0a2218",letterSpacing:5,marginBottom:8}}>SHARP MFP DIAGNOSTICS</div>
            <div style={{fontSize:9,color:"#112211",letterSpacing:3,marginBottom:44}}>AUTHORIZED TECHNICIANS ONLY</div>
            <div style={{fontSize:10,color:"#1a3322",letterSpacing:3,marginBottom:10}}>ENTER ACCESS CODE <span className="blink" style={{color:"#00ff88"}}>_</span></div>
            <input
              style={{width:"100%",background:"#000",border:`1px solid ${accessError?"rgba(255,60,60,.6)":"rgba(0,255,136,.18)"}`,color:accessError?"#ff4444":"#00ff88",fontFamily:"'Share Tech Mono',monospace",fontSize:22,padding:"14px 20px",letterSpacing:10,textAlign:"center",outline:"none"}}
              type="password" placeholder="••••••••"
              value={accessInput}
              onChange={e=>{setAccessInput(e.target.value);setAccessError(false);}}
              onKeyDown={e=>e.key==="Enter"&&handleAccess()}
              autoFocus
            />
            <button onClick={handleAccess}
              style={{width:"100%",marginTop:14,padding:"14px",background:"transparent",border:"1px solid rgba(0,255,136,.28)",color:"#00ff88",fontFamily:"'Orbitron',monospace",fontSize:11,fontWeight:700,letterSpacing:4,cursor:"pointer"}}
              onMouseEnter={e=>{e.target.style.background="rgba(0,255,136,.07)";e.target.style.borderColor="rgba(0,255,136,.55)";}}
              onMouseLeave={e=>{e.target.style.background="transparent";e.target.style.borderColor="rgba(0,255,136,.28)";}}
            >AUTHENTICATE →</button>
            {accessError && <div style={{color:"#ff4444",fontSize:10,letterSpacing:2,marginTop:14}}>⚠ INVALID CODE — ACCESS DENIED</div>}
          </div>
        </div>
      )}

      {/* ── SELECT ── */}
      {phase==="select" && (
        <div style={{minHeight:"100vh",display:"flex",flexDirection:"column",position:"relative",zIndex:10}}>
          <div style={{borderBottom:"1px solid rgba(0,255,136,.1)",background:"rgba(0,3,2,.98)",padding:"0 32px",height:62,display:"flex",alignItems:"center",justifyContent:"space-between"}}>
            <div style={{display:"flex",alignItems:"center",gap:12}}>
              <div style={{fontFamily:"'Orbitron',monospace",fontSize:20,fontWeight:900,color:"#fff",letterSpacing:2}}>A<span style={{color:"#00ff88"}}>·</span>ONE<span style={{color:"#00ff88",fontSize:16}}> AI</span></div>
              <div style={{width:1,height:20,background:"rgba(0,255,136,.15)"}}/>
              <div style={{fontSize:9,color:"#224433",letterSpacing:3}}>SHARP MFP DIAGNOSTICS</div>
            </div>
            <div style={{fontSize:9,color:"#1a3322",letterSpacing:3}}>SELECT MODEL</div>
          </div>
          <div style={{padding:"44px 32px",flex:1}}>
            <div style={{fontFamily:"'Orbitron',monospace",fontSize:11,color:"#00ff88",letterSpacing:6,marginBottom:6}}>MODEL SELECTION</div>
            <div style={{fontSize:10,color:"#1a3322",letterSpacing:2,marginBottom:8}}>Section 7 · Self Diagnostics &amp; Trouble Codes loaded instantly per model</div>
            <div style={{fontSize:9,color:"#0f1f0f",letterSpacing:1,marginBottom:32,padding:"8px 12px",border:"1px solid rgba(0,255,136,.06)",display:"inline-block"}}>
              ⚡ Content sourced exclusively from official Sharp service manual Section 7
            </div>
            <div style={{display:"grid",gridTemplateColumns:"repeat(auto-fill,minmax(290px,1fr))",gap:14}}>
              {MANUALS.map(m=>(
                <div key={m.id} onClick={()=>selectManual(m)}
                  style={{border:"1px solid rgba(0,255,136,.09)",background:"rgba(0,5,2,.85)",padding:"22px 24px",cursor:"pointer",position:"relative",transition:"all .2s"}}
                  onMouseEnter={e=>{e.currentTarget.style.borderColor=`${m.color}55`;e.currentTarget.style.transform="translateY(-2px)";e.currentTarget.style.boxShadow=`0 6px 30px ${m.color}0d`;}}
                  onMouseLeave={e=>{e.currentTarget.style.borderColor="rgba(0,255,136,.09)";e.currentTarget.style.transform="";e.currentTarget.style.boxShadow="";}}
                >
                  <div style={{position:"absolute",top:0,left:0,right:0,height:1,background:`linear-gradient(90deg,transparent,${m.color}33,transparent)`}}/>
                  <div style={{display:"flex",justifyContent:"space-between",alignItems:"flex-start",marginBottom:12}}>
                    <div style={{fontFamily:"'Orbitron',monospace",fontSize:12,fontWeight:700,color:"#fff",letterSpacing:1,lineHeight:1.4}}>{m.label}</div>
                    <div style={{fontSize:8,letterSpacing:2,padding:"3px 8px",border:`1px solid ${m.color}33`,color:m.color,flexShrink:0,marginLeft:8}}>{m.subtitle.includes("Color")?"COLOR":"B&W"}</div>
                  </div>
                  <div style={{fontSize:9,color:"#2a5542",letterSpacing:2,marginBottom:8}}>{m.subtitle}</div>
                  <div style={{fontSize:9,color:"#152515",lineHeight:1.9}}>{m.models}</div>
                  <div style={{marginTop:14,fontSize:8,color:`${m.color}55`,letterSpacing:2}}>SECTION 7 · SELF DIAG &amp; TROUBLE CODES</div>
                  <div style={{position:"absolute",bottom:16,right:18,fontFamily:"'Orbitron',monospace",fontSize:9,fontWeight:700,color:m.color,opacity:.45}}>LOAD →</div>
                </div>
              ))}
            </div>
          </div>
        </div>
      )}

      {/* ── CHAT ── */}
      {phase==="chat" && (
        <div className={glitch?"glitch":""} style={{minHeight:"100vh",display:"flex",flexDirection:"column",position:"relative",zIndex:10}}>
          {/* header */}
          <div style={{borderBottom:"1px solid rgba(0,255,136,.1)",background:"rgba(0,3,2,.98)",padding:"0 22px",height:58,display:"flex",alignItems:"center",justifyContent:"space-between",flexShrink:0}}>
            <div style={{display:"flex",alignItems:"center",gap:14}}>
              <button onClick={()=>{setPhase("select");setMessages([]);setSelectedManual(null);}}
                style={{background:"transparent",border:"1px solid rgba(0,255,136,.12)",color:"#2a4a3a",fontFamily:"'Share Tech Mono',monospace",fontSize:9,letterSpacing:2,padding:"5px 12px",cursor:"pointer"}}
                onMouseEnter={e=>{e.target.style.borderColor="rgba(0,255,136,.3)";e.target.style.color="#00ff88";}}
                onMouseLeave={e=>{e.target.style.borderColor="rgba(0,255,136,.12)";e.target.style.color="#2a4a3a";}}
              >← MODELS</button>
              <div style={{fontFamily:"'Orbitron',monospace",fontSize:17,fontWeight:900,color:"#fff",letterSpacing:2}}>A<span style={{color:"#00ff88"}}>·</span>ONE<span style={{color:"#00ff88",fontSize:13}}> AI</span></div>
              <div style={{width:1,height:16,background:"rgba(0,255,136,.12)"}}/>
              <div style={{display:"flex",alignItems:"center",gap:6}}>
                <div style={{width:5,height:5,borderRadius:"50%",background:accent,boxShadow:`0 0 8px ${accent}`}}/>
                <div style={{fontSize:9,color:accent,letterSpacing:3}}>LIVE</div>
              </div>
            </div>
            <div style={{display:"flex",flexDirection:"column",alignItems:"flex-end",gap:2}}>
              <div style={{fontSize:9,letterSpacing:1,padding:"4px 12px",border:`1px solid ${accent}33`,color:accent,background:"rgba(0,0,0,.5)"}}>{selectedManual?.label}</div>
              <div style={{fontSize:8,color:"#0f2010",letterSpacing:2}}>SECTION 7 · SELF DIAG</div>
            </div>
          </div>

          {/* messages */}
          <div style={{flex:1,overflowY:"auto",padding:"24px 28px",display:"flex",flexDirection:"column",gap:18}}>
            {messages.map((m,i)=>(
              <div key={i} style={{display:"flex",gap:12,alignItems:"flex-start"}}>
                <div style={{width:32,height:32,flexShrink:0,display:"flex",alignItems:"center",justifyContent:"center",fontFamily:"'Orbitron',monospace",fontSize:8,fontWeight:700,border:`1px solid ${m.role==="assistant"?`${accent}44`:"rgba(255,255,255,.1)"}`,color:m.role==="assistant"?accent:"rgba(255,255,255,.25)",background:m.role==="assistant"?`${accent}08`:"rgba(255,255,255,.02)"}}>
                  {m.role==="user"?"TCH":"AI"}
                </div>
                <div style={{flex:1}}>
                  <div style={{fontSize:8,letterSpacing:3,marginBottom:7,color:m.role==="assistant"?`${accent}aa`:"#2a3a2a"}}>
                    {m.role==="user"?"TECHNICIAN":`AONE-AI · ${selectedManual?.label} · SEC.7`}
                  </div>
                  <div style={{fontSize:13,lineHeight:1.9,color:m.role==="assistant"?"#ccc":"#5a7a5a"}} dangerouslySetInnerHTML={{__html:fmt(m.content)}}/>
                </div>
              </div>
            ))}
            {aiLoading && (
              <div style={{display:"flex",gap:12,alignItems:"flex-start"}}>
                <div style={{width:32,height:32,flexShrink:0,display:"flex",alignItems:"center",justifyContent:"center",fontFamily:"'Orbitron',monospace",fontSize:8,fontWeight:700,border:`1px solid ${accent}44`,color:accent,background:`${accent}08`}}>AI</div>
                <div style={{flex:1}}>
                  <div style={{fontSize:8,letterSpacing:3,marginBottom:10,color:`${accent}aa`}}>{`AONE-AI · ${selectedManual?.label} · SEC.7`}</div>
                  <div style={{display:"flex",gap:5}}>
                    {[0,.2,.4].map((d,i)=><div key={i} style={{width:5,height:5,background:accent,borderRadius:"50%",animation:`tda 1.2s ${d}s ease-in-out infinite`}}/>)}
                  </div>
                </div>
              </div>
            )}
            <div ref={chatEndRef}/>
          </div>

          {/* input */}
          <div style={{borderTop:"1px solid rgba(0,255,136,.08)",background:"rgba(0,3,2,.98)",padding:"16px 24px",display:"flex",alignItems:"flex-end",gap:10,flexShrink:0}}>
            <div style={{color:"#00ff88",fontSize:15,paddingBottom:11,flexShrink:0}}>&gt;_</div>
            <textarea ref={inputRef}
              style={{flex:1,background:"transparent",border:"none",borderBottom:`1px solid rgba(0,255,136,.15)`,fontFamily:"'Share Tech Mono',monospace",fontSize:13,padding:"9px 0",outline:"none",resize:"none",lineHeight:1.6,caretColor:"#00ff88"}}
              placeholder={`Enter error code or question for ${selectedManual?.label}...`}
              value={input} rows={1}
              onChange={e=>setInput(e.target.value)}
              onKeyDown={e=>{if(e.key==="Enter"&&!e.shiftKey){e.preventDefault();sendMessage();}}}
            />
            <button onClick={sendMessage} disabled={aiLoading||!input.trim()}
              style={{background:"transparent",border:`1px solid ${accent}44`,color:accent,fontFamily:"'Orbitron',monospace",fontSize:10,fontWeight:700,letterSpacing:2,padding:"9px 20px",cursor:"pointer",flexShrink:0,opacity:(aiLoading||!input.trim())?.25:1}}
              onMouseEnter={e=>{if(!aiLoading&&input.trim()){e.target.style.background=`${accent}12`;e.target.style.borderColor=accent;}}}
              onMouseLeave={e=>{e.target.style.background="transparent";e.target.style.borderColor=`${accent}44`;}}
            >SEND</button>
          </div>
        </div>
      )}
    </div>
  );
}
